import{_ as t,o as e,c as d,Q as o}from"./chunks/framework.48927342.js";const m=JSON.parse('{"title":"Personal Pronouns and Verb Conjugation","description":"","frontmatter":{},"headers":[],"relativePath":"en/more/maltese/grammar/03-person-conjugation.md","filePath":"en/more/maltese/grammar/03-person-conjugation.md"}'),a={name:"en/more/maltese/grammar/03-person-conjugation.md"},r=o('<h1 id="personal-pronouns-and-verb-conjugation" tabindex="-1">Personal Pronouns and Verb Conjugation <a class="header-anchor" href="#personal-pronouns-and-verb-conjugation" aria-label="Permalink to &quot;Personal Pronouns and Verb Conjugation&quot;">​</a></h1><h2 id="_1-person-markers-and-conjugation-patterns" tabindex="-1">1. Person Markers and Conjugation Patterns <a class="header-anchor" href="#_1-person-markers-and-conjugation-patterns" aria-label="Permalink to &quot;1. Person Markers and Conjugation Patterns&quot;">​</a></h2><p>Maltese verbs change according to the person and number of the subject. Pronouns can usually be omitted because the verb form often identifies the person; use them for emphasis or contrast. <code>hu</code> (he) and <code>hi</code> (she) distinguish masculine and feminine third-person singular. <code>inti</code> (you, singular) is used for any gender.</p><p>A common pattern is “person prefix + verb stem”: first person often uses <code>n-</code>, second person <code>t-</code>, and third-person masculine <code>j-</code>. Third-person feminine often has the same form as second-person singular. Plural forms commonly use a plural stem or the ending <code>-u</code>. For example, <code>kiteb</code> (write):</p><table><thead><tr><th>Person</th><th>Pronoun</th><th>Common marker</th><th>Form of <code>kiteb</code></th></tr></thead><tbody><tr><td>First-person singular</td><td>jien</td><td>n-</td><td>nikteb</td></tr><tr><td>Second-person singular</td><td>inti</td><td>t-</td><td>tikteb</td></tr><tr><td>Third-person singular masculine</td><td>hu</td><td>j-</td><td>jikteb</td></tr><tr><td>Third-person singular feminine</td><td>hi</td><td>t-</td><td>tikteb</td></tr><tr><td>First-person plural</td><td>aħna</td><td>n- + plural stem</td><td>niktbu</td></tr><tr><td>Second-person plural</td><td>intom</td><td>t- + plural stem</td><td>tiktbu</td></tr><tr><td>Third-person plural</td><td>huma</td><td>j- + plural stem</td><td>jiktbu</td></tr></tbody></table><p>This is a common template, not a mechanical rule for every verb. Stem type and stem changes must be learned for each verb.</p><h3 id="initial-and-medial-għ" tabindex="-1">Initial and Medial <code>għ</code> <a class="header-anchor" href="#initial-and-medial-għ" aria-label="Permalink to &quot;Initial and Medial `għ`&quot;">​</a></h3><ul><li>When a root begins with <code>għ</code>, the letters usually remain in the spelling after the person prefix, while the stem vowel may change: <code>għen</code> → <code>ngħin</code>, <code>għex</code> → <code>ngħix</code>.</li><li>When <code>għ</code> occurs inside a root, it usually remains in the spelling; vowels or other parts of the stem may change: <code>bagħat</code> → <code>nibgħat</code>, <code>qagħad</code> → <code>noqgħod</code>, <code>biegħ</code> → <code>nbigħ</code>.</li><li>Use “person prefix + the relevant stem pattern” as a guide. There is no single character-substitution formula for every <code>għ</code> verb; learn each verb&#39;s forms.</li></ul><h2 id="_2-full-conjugation-of-15-verbs" tabindex="-1">2. Full Conjugation of 15 Verbs <a class="header-anchor" href="#_2-full-conjugation-of-15-verbs" aria-label="Permalink to &quot;2. Full Conjugation of 15 Verbs&quot;">​</a></h2><p>The table contains five common verbs, five verbs with initial <code>għ</code>, and five with medial <code>għ</code>. The glosses are given in English. Each of the seven persons has its own column. These are person forms only; tense is not discussed here.</p><table><thead><tr><th>English</th><th>Malti citation form</th><th>jien</th><th>inti</th><th>hu</th><th>hi</th><th>aħna</th><th>intom</th><th>huma</th></tr></thead><tbody><tr><td>eat</td><td>kiel</td><td><code>niekol</code></td><td><code>tiekol</code></td><td><code>jiekol</code></td><td><code>tiekol</code></td><td><code>nieklu</code></td><td><code>tieklu</code></td><td><code>jieklu</code></td></tr><tr><td>drink</td><td>xorob</td><td><code>nixrob</code></td><td><code>tixrob</code></td><td><code>jixrob</code></td><td><code>tixrob</code></td><td><code>nixorbu</code></td><td><code>tixorbu</code></td><td><code>jixorbu</code></td></tr><tr><td>go</td><td>mar</td><td><code>mmur</code></td><td><code>tmur</code></td><td><code>jmur</code></td><td><code>tmur</code></td><td><code>mmorru</code></td><td><code>tmorru</code></td><td><code>jmorru</code></td></tr><tr><td>write</td><td>kiteb</td><td><code>nikteb</code></td><td><code>tikteb</code></td><td><code>jikteb</code></td><td><code>tikteb</code></td><td><code>niktbu</code></td><td><code>tiktbu</code></td><td><code>jiktbu</code></td></tr><tr><td>read</td><td>qara</td><td><code>naqra</code></td><td><code>taqra</code></td><td><code>jaqra</code></td><td><code>taqra</code></td><td><code>naqraw</code></td><td><code>taqraw</code></td><td><code>jaqraw</code></td></tr><tr><td>make/do</td><td>għamel</td><td><code>nagħmel</code></td><td><code>tagħmel</code></td><td><code>jagħmel</code></td><td><code>tagħmel</code></td><td><code>nagħmlu</code></td><td><code>tagħmlu</code></td><td><code>jagħmlu</code></td></tr><tr><td>help</td><td>għen</td><td><code>ngħin</code></td><td><code>tgħin</code></td><td><code>jgħin</code></td><td><code>tgħin</code></td><td><code>ngħinu</code></td><td><code>tgħinu</code></td><td><code>jgħinu</code></td></tr><tr><td>live</td><td>għex</td><td><code>ngħix</code></td><td><code>tgħix</code></td><td><code>jgħix</code></td><td><code>tgħix</code></td><td><code>ngħixu</code></td><td><code>tgħixu</code></td><td><code>jgħixu</code></td></tr><tr><td>close</td><td>għalaq</td><td><code>nagħlaq</code></td><td><code>tagħlaq</code></td><td><code>jagħlaq</code></td><td><code>tagħlaq</code></td><td><code>nagħlqu</code></td><td><code>tagħlqu</code></td><td><code>jagħlqu</code></td></tr><tr><td>choose</td><td>għażel</td><td><code>nagħżel</code></td><td><code>tagħżel</code></td><td><code>jagħżel</code></td><td><code>tagħżel</code></td><td><code>nagħżlu</code></td><td><code>tagħżlu</code></td><td><code>jagħżlu</code></td></tr><tr><td>send</td><td>bagħat</td><td><code>nibgħat</code></td><td><code>tibgħat</code></td><td><code>jibgħat</code></td><td><code>tibgħat</code></td><td><code>nibagħtu</code></td><td><code>tibagħtu</code></td><td><code>jibagħtu</code></td></tr><tr><td>stay</td><td>qagħad</td><td><code>noqgħod</code></td><td><code>toqgħod</code></td><td><code>joqgħod</code></td><td><code>toqgħod</code></td><td><code>noqogħdu</code></td><td><code>toqogħdu</code></td><td><code>joqogħdu</code></td></tr><tr><td>sell</td><td>biegħ</td><td><code>nbigħ</code></td><td><code>tbigħ</code></td><td><code>jbigħ</code></td><td><code>tbigħ</code></td><td><code>nbigħu</code></td><td><code>tbigħu</code></td><td><code>jbigħu</code></td></tr><tr><td>switch on (a light)</td><td>xegħel</td><td><code>nixgħel</code></td><td><code>tixgħel</code></td><td><code>jixgħel</code></td><td><code>tixgħel</code></td><td><code>nixegħlu</code></td><td><code>tixegħlu</code></td><td><code>jixegħlu</code></td></tr><tr><td>be surprised</td><td>stagħġeb</td><td><code>nistagħġeb</code></td><td><code>tistagħġeb</code></td><td><code>jistagħġeb</code></td><td><code>tistagħġeb</code></td><td><code>nistagħġbu</code></td><td><code>tistagħġbu</code></td><td><code>jistagħġbu</code></td></tr></tbody></table><h3 id="example-sentences" tabindex="-1">Example Sentences <a class="header-anchor" href="#example-sentences" aria-label="Permalink to &quot;Example Sentences&quot;">​</a></h3><p>Each verb is illustrated with one person. Examples are shown in English and Maltese.</p><table><thead><tr><th>Verb</th><th>English</th><th>Malti</th></tr></thead><tbody><tr><td>kiel</td><td>We eat bread.</td><td>Aħna nieklu l-ħobż.</td></tr><tr><td>xorob</td><td>She drinks water.</td><td>Hi tixrob l-ilma.</td></tr><tr><td>mar</td><td>You go home.</td><td>Inti tmur id-dar.</td></tr><tr><td>kiteb</td><td>They write a letter.</td><td>Huma jiktbu ittra.</td></tr><tr><td>qara</td><td>He reads a book.</td><td>Hu jaqra ktieb.</td></tr><tr><td>għamel</td><td>I make dinner.</td><td>Jien nagħmel l-ikla ta&#39; filgħaxija.</td></tr><tr><td>għen</td><td>You help a friend.</td><td>Inti tgħin lil ħabib.</td></tr><tr><td>għex</td><td>They live in Malta.</td><td>Huma jgħixu f&#39;Malta.</td></tr><tr><td>għalaq</td><td>She closes the door.</td><td>Hi tagħlaq il-bieb.</td></tr><tr><td>għażel</td><td>We choose a book.</td><td>Aħna nagħżlu ktieb.</td></tr><tr><td>bagħat</td><td>I send a message.</td><td>Jien nibgħat messaġġ.</td></tr><tr><td>qagħad</td><td>He stays at home.</td><td>Hu joqgħod id-dar.</td></tr><tr><td>biegħ</td><td>You sell books.</td><td>Inti tbigħ kotba.</td></tr><tr><td>xegħel</td><td>We switch on the light.</td><td>Aħna nixegħlu d-dawl.</td></tr><tr><td>stagħġeb</td><td>They are surprised.</td><td>Huma jistagħġbu.</td></tr></tbody></table><p>Maltese commonly omits a separate verb “to be” when stating identity, for example <code>Jien student.</code> (I am a student.)</p><h2 id="_3-gender-and-agreement" tabindex="-1">3. Gender and Agreement <a class="header-anchor" href="#_3-gender-and-agreement" aria-label="Permalink to &quot;3. Gender and Agreement&quot;">​</a></h2><ul><li><code>hu</code> and <code>hi</code> distinguish masculine and feminine; third-person verb forms may also differ, for example <code>jikteb</code> (he writes) and <code>tikteb</code> (she writes).</li><li>Second-person singular <code>inti</code> is used for any gender; the verb forms in the examples above are the same.</li><li>Nouns and adjectives may agree in gender and number: <code>tifel tajjeb</code> (a good boy), <code>tifla tajba</code> (a good girl).</li><li>Plural verb forms often use their own endings. Do not generalize one verb&#39;s conjugation to every root.</li></ul><h2 id="_4-practice-patterns" tabindex="-1">4. Practice Patterns <a class="header-anchor" href="#_4-practice-patterns" aria-label="Permalink to &quot;4. Practice Patterns&quot;">​</a></h2><p>Substitute a verb into the patterns below, then change the subject:</p><ul><li><code>Jien ___ il-ħobż.</code>: I ___ bread.</li><li><code>Hi ___ l-ilma.</code>: She ___ water.</li><li><code>Aħna ___ id-dar.</code>: We ___ home / at home.</li></ul><p>Learn a verb form together with an example. For irregular verbs and loan verbs, consult a full conjugation table.</p><h2 id="_5-reference-entries" tabindex="-1">5. Reference Entries <a class="header-anchor" href="#_5-reference-entries" aria-label="Permalink to &quot;5. Reference Entries&quot;">​</a></h2><ul><li><a href="https://en.wiktionary.org/wiki/g%C4%A7amel#Maltese" target="_blank" rel="noreferrer">Wiktionary: għamel</a></li><li><a href="https://en.wiktionary.org/wiki/qag%C4%A7ad#Maltese" target="_blank" rel="noreferrer">Wiktionary: qagħad</a></li><li><a href="https://en.wiktionary.org/wiki/bag%C4%A7at#Maltese" target="_blank" rel="noreferrer">Wiktionary: bagħat</a></li><li><a href="https://en.wiktionary.org/wiki/g%C4%A7en#Maltese" target="_blank" rel="noreferrer">Wiktionary: għen</a></li></ul>',23),n=[r];function i(c,l,s,g,h,u){return e(),d("div",null,n)}const p=t(a,[["render",i]]);export{m as __pageData,p as default};
